import{_ as t,o as r,c as e,a8 as n}from"./chunks/framework.BWjTbCIc.js";const d=JSON.parse('{"title":"福建中学 · 年份未注明 · 中一 · 面试","description":"","frontmatter":{"schema":"exam-report-v3","generated_from":"assets/exam-feedback","school_slug":"fukien","school_zh":"福建中学","school_en":"Fukien Secondary School","grade":"s1","year":"unknown","year_label":"年份未注明","type":"interview","title":"福建中学 · 年份未注明 · 中一 · 面试","anonymous":true,"source_ids":["FMS-S1-HIST-POCKET-MONEY","M011-u","M061-M062"],"rounds":["r1","unknown"]},"headers":[],"relativePath":"reports/fukien/s1/unknown-interview.md","filePath":"reports/fukien/s1/unknown-interview.md"}'),s={name:"reports/fukien/s1/unknown-interview.md"};function p(l,o,a,i,g,c){return r(),e("div",null,[...o[0]||(o[0]=[n('<h1 id="福建中学-·-年份未注明-·-中一-·-面试" tabindex="-1">福建中学 · 年份未注明 · 中一 · 面试 <a class="header-anchor" href="#福建中学-·-年份未注明-·-中一-·-面试" aria-label="Permalink to &quot;福建中学 · 年份未注明 · 中一 · 面试&quot;">​</a></h1><p><a href="/hk-exam-web/schools/fukien">← 返回福建中学资料库</a></p><blockquote><p>以下内容根据考试及面试资料整理，已作匿名化与书面化处理，非逐字实录。具体安排请以当次考试通知为准。</p></blockquote><h2 id="record-fms-s1-hist-pocket-money" tabindex="-1">资料来源：福建中學及附屬小學_全考試流程彙整報告.pdf <a class="header-anchor" href="#record-fms-s1-hist-pocket-money" aria-label="Permalink to &quot;资料来源：福建中學及附屬小學_全考試流程彙整報告.pdf {#record-fms-s1-hist-pocket-money}&quot;">​</a></h2><p><strong>资料类型：</strong> 历史面试流程整理</p><p><strong>入学途径：</strong> 中一入学</p><p><strong>课程分支：</strong> 课程分支未注明</p><h3 id="第一轮-·-原文明示" tabindex="-1">第一轮 · 原文明示 <a class="header-anchor" href="#第一轮-·-原文明示" aria-label="Permalink to &quot;第一轮 · 原文明示&quot;">​</a></h3><blockquote><p><strong>英语：</strong> 英语</p><p><strong>生活问答</strong></p><p>询问是否有零用钱，以及通常如何使用。</p><p><strong>四格图讲故事</strong></p><p>根据小红帽舞台剧主题的四格图讲述故事，并补充结局。</p></blockquote><blockquote><p><strong>数学：</strong> 语言未注明</p><p><strong>平板评估</strong></p><p>以iPad作答，涉及周界与面积。</p></blockquote><h2 id="record-m011-u" tabindex="-1">资料来源：【其它机构】升中面试经验汇总_18-21.pdf <a class="header-anchor" href="#record-m011-u" aria-label="Permalink to &quot;资料来源：【其它机构】升中面试经验汇总_18-21.pdf {#record-m011-u}&quot;">​</a></h2><p><strong>资料类型：</strong> 面试反馈</p><p><strong>入学途径：</strong> 未注明</p><p><strong>课程分支：</strong> 课程分支未注明</p><h3 id="轮次未注明-·-请以当次考试通知为准" tabindex="-1">轮次未注明 · 请以当次考试通知为准 <a class="header-anchor" href="#轮次未注明-·-请以当次考试通知为准" aria-label="Permalink to &quot;轮次未注明 · 请以当次考试通知为准&quot;">​</a></h3><blockquote><p><strong>英语：</strong> 英语</p><p><strong>閱讀與選校問答</strong></p><ul><li>閱讀短文後回答問題。</li><li>選校問題原文：“What reasons will you join this school ?”</li></ul></blockquote><blockquote><p><strong>语文：</strong> 中文（口语未注明）</p><p><strong>個人與家庭問答</strong></p><ul><li>以一種動作形容自己的性格，並說明強項與弱項。</li><li>回答住址、父母職業、生日及年齡。</li></ul><p><strong>閱讀與詩歌理解</strong></p><ul><li>閱讀一首詩並作解釋。</li><li>閱讀短文後回答問題。</li></ul></blockquote><blockquote><p><strong>数学：</strong> 语言未注明</p><p><strong>電腦作答</strong></p><p>考生使用電腦完成數學題。</p></blockquote><blockquote><p><strong>综合面试：</strong> 语言未注明</p><p><strong>小組合作</strong></p><p>小組討論包含合作遊戲；材料列出按圖片砌積木，以及使用LEGO砌警局的任務。</p></blockquote><h2 id="record-m061-m062" tabindex="-1">资料来源：升中面試 － 福建中學.docx <a class="header-anchor" href="#record-m061-m062" aria-label="Permalink to &quot;资料来源：升中面試 － 福建中學.docx {#record-m061-m062}&quot;">​</a></h2><p><strong>资料类型：</strong> 往届题目整理</p><p><strong>入学途径：</strong> 未注明</p><p><strong>课程分支：</strong> 课程分支未注明</p><h3 id="轮次未注明-·-请以当次考试通知为准-1" tabindex="-1">轮次未注明 · 请以当次考试通知为准 <a class="header-anchor" href="#轮次未注明-·-请以当次考试通知为准-1" aria-label="Permalink to &quot;轮次未注明 · 请以当次考试通知为准&quot;">​</a></h3><blockquote><p><strong>资料填写：</strong> 中文／英语</p><p><strong>个人资料表</strong></p><p>填寫中文及英文個人資料表。</p></blockquote><blockquote><p><strong>综合面试：</strong> 普通话／英语</p><p><strong>面试方式</strong></p><p>以普通話及英語作自我介紹。</p></blockquote><blockquote><p><strong>综合面试：</strong> 语言未注明</p><p><strong>個人問答</strong></p><p>題目涉及以下內容：</p><ul><li>曾獲得的獎項。</li><li>喜歡閱讀的書籍。</li><li>個人優點、缺點及專長。</li><li>喜歡這所學校的哪些方面。</li></ul><p><strong>合作活動</strong></p><p>與另外幾位同學一起拼砌積木。</p></blockquote><blockquote><p><strong>语文：</strong> 普通话</p><p><strong>语文问答</strong></p><p>以普通話回答：「你認為甚麼品格最值得擁有？」</p></blockquote><blockquote><p><strong>综合面试：</strong> 语言未注明</p><p><strong>面试方式</strong></p><p>材料整理的往屆面試題包括：</p><ul><li>「你為甚麼會選擇福建中學？」</li><li>「你有參加甚麼課外活動嗎？」</li><li>是否曾加入校隊。</li><li>「你平時喜不喜歡打遊戲機？」</li><li>「如果你不打遊戲機，但你的同學會打遊戲機，會不會少了話題？」</li><li>問及香港時事，並追問：「你是否同意政府的做法？」</li></ul></blockquote><blockquote><p><strong>语文：</strong> 中文（口语未注明）</p><p><strong>詞語說故事</strong></p><p>用三個指定詞語說故事：「酒樓、祖先三代、其樂融融」。</p><p><strong>文言文閱讀</strong></p><p>閱讀《鄭人買履》一篇。</p></blockquote>',30)])])}const h=t(s,[["render",p]]);export{d as __pageData,h as default};
